    gpio_put(PIN_DATA_CMD, 0);
    gpio_put(PIN_CS, 0);
    spi_write_byte(cmd);
    for (int i = 0; i < param_count; i++) {
        spi_write_byte(params[i]);
    }
    gpio_put(PIN_CS, 1);
}

// Send a block of pixel bytes in a single CS assertion
static void send_pixel_block(const uint8_t *data, int count) {
    gpio_put(PIN_DATA_CMD, 1);
    gpio_put(PIN_CS, 0);
    spi_write_blocking(SPI_PORT, data, count);
    gpio_put(PIN_CS, 1);
}

int main() {
    stdio_init_all();

    spi_init(SPI_PORT, 1000 * 1000);
    gpio_set_function(PIN_MOSI, GPIO_FUNC_SPI);
    gpio_set_function(PIN_SCK, GPIO_FUNC_SPI);
    gpio_set_function(PIN_CS, GPIO_FUNC_SIO);
    gpio_set_function(PIN_DATA_CMD, GPIO_FUNC_SIO);

    gpio_set_dir(PIN_CS, GPIO_OUT);
    gpio_set_dir(PIN_DATA_CMD, GPIO_OUT);
    gpio_put(PIN_CS, 1);
    gpio_put(PIN_DATA_CMD, 1);

    // Turn display on
    send_command(CMD_DISPLAYON, NULL, 0);
    sleep_ms(50);

    // Write a red block at the top-left corner of the screen
    // Window: columns 0..63, rows 0..31 = 64x32 pixels
    uint8_t col_params[] = {0x00, 0x00, 0x00, 0x3F};
    uint8_t row_params[] = {0x00, 0x00, 0x00, 0x1F};
    send_command(CMD_SETCOLUMNADDRESS, col_params, 4);
    send_command(CMD_SETROWADDRESS, row_params, 4);

    // Fill the window with red pixels. Each pixel is 2 bytes (RGB565).
    const int pixel_count = 64 * 32;
    uint8_t pixel_data[2] = {(COLOR_RED >> 8) & 0xFF, COLOR_RED & 0xFF};

    for (int row = 0; row < 32; row++) {
        for (int col = 0; col < 64; col++) {
            send_pixel_block(pixel_data, 2);
        }
    }

    while (true) {
        sleep_ms(1000);
    }
}
